"use client";
import { type CSSProperties, type ReactNode, type RefObject } from "react";
import {
  sectionStyles,
  useSectionEnvironment,
  useSectionScroll,
  type SectionInternalGroup,
  type SectionInternalLink,
} from "./section-shared";
export interface GradientFooterLink extends SectionInternalLink {}
export interface GradientFooterGroup extends SectionInternalGroup {}
export interface GradientFooterProps {
  brand: string;
  groups: readonly GradientFooterGroup[];
  copyright?: ReactNode;
  legalLinks?: readonly GradientFooterLink[];
  children?: ReactNode;
  onNavigate?: (link: GradientFooterLink) => void;
  glowColor?: string;
  background?: string;
  revealDistance?: number;
  scrollContainer?: RefObject<HTMLElement | null>;
  onProgress?: (progress: number) => void;
  height?: number;
  className?: string;
  style?: CSSProperties;
}
/** Scroll-revealed footer with a bottom glow and typography measured by an SVG text box. */
export function GradientFooter({
  brand,
  groups,
  copyright,
  legalLinks = [],
  children,
  onNavigate,
  glowColor = "#bdd13a",
  background = "#0b0b0b",
  revealDistance = 600,
  scrollContainer,
  onProgress,
  height = 720,
  className = "",
  style,
}: GradientFooterProps) {
  const env = useSectionEnvironment(),
    progress = useSectionScroll(env.ref, scrollContainer, onProgress);
  return (
    <div
      ref={env.ref}
      className={`z-as z-as-gradient-footer ${className}`}
      data-section="gradient-footer"
      data-progress={progress.toFixed(4)}
      style={
        {
          height: `calc(min(${height}px,100svh) + ${Math.max(0, revealDistance)}px)`,
          "--section-height": `${height}px`,
          ...style,
        } as CSSProperties
      }
    >
      <style>
        {sectionStyles +
          `.z-as-gradient-footer .z-as-gradient-surface{position:absolute;inset:0;padding:60px 4.4% 0;color:#aaa;overflow:hidden;display:flex;flex-direction:column}.z-as-gradient-footer .z-as-gradient-columns{position:relative;z-index:2;display:grid;grid-template-columns:repeat(4,1fr);gap:25px}.z-as-gradient-footer .z-as-links h3{font-size:11px;letter-spacing:.1em;text-transform:uppercase;font-weight:400;margin-bottom:15px;color:#666}.z-as-gradient-footer .z-as-links a{font-size:14px}.z-as-gradient-footer .z-as-gradient-legal{position:relative;z-index:2;display:flex;align-items:center;gap:20px;flex-wrap:wrap;font-size:12px;margin-top:45px}.z-as-gradient-footer .z-as-gradient-legal a{text-decoration:none}.z-as-gradient-footer .z-as-gradient-legal button{margin-left:auto;background:none}.z-as-gradient-footer .z-as-gradient-word{position:relative;width:100%;margin-top:auto;display:block;overflow:visible;z-index:1;flex:none}.z-as-gradient-footer .z-as-gradient-cover{position:absolute;inset:0;z-index:3;background:#efefef;display:grid;place-items:center;color:#888;pointer-events:none}.z-as-gradient-footer .z-as-gradient-cover small{position:absolute;bottom:28px;letter-spacing:.2em;font-size:10px}@media(max-width:600px){.z-as-gradient-footer .z-as-gradient-surface{padding:30px 20px 0}.z-as-gradient-footer .z-as-gradient-columns{grid-template-columns:repeat(2,1fr);gap:22px}.z-as-gradient-footer .z-as-links a{font-size:12px}.z-as-gradient-footer .z-as-links h3{margin-bottom:7px}.z-as-gradient-footer .z-as-gradient-legal{margin-top:25px;gap:12px;font-size:10px}}`}
      </style>
      <div className="z-as-pin">
        <footer className="z-as-gradient-surface"
          inert={progress <= 0 && revealDistance > 0} style={{ background }}>
          <div
            className="z-as-fill"
            data-gradient-glow=""
            style={{
              background: `radial-gradient(ellipse 90% 65% at 50% 115%,${glowColor},transparent)`,
              opacity: env.reduced ? 1 : progress,
              transform: `translateY(${(1 - progress) * 30}%)`,
            }}
          />
          <div className="z-as-gradient-columns">
            {groups.map((group, i) => (
              <div
                key={group.title}
                className="z-as-links"
                style={{
                  transform: `translateY(${env.reduced ? 0 : Math.max(0, 1 - progress * 1.8 + i * 0.08) * 45}px)`,
                  opacity: env.reduced ? 1 : Math.min(1, progress * 2),
                }}
              >
                <h3>{group.title}</h3>
                {group.links.map((link) => (
                  <a
                    key={link.href + link.label}
                    href={link.href}
                    onClick={() => onNavigate?.(link)}
                  >
                    {link.label}
                  </a>
                ))}
              </div>
            ))}
          </div>
          <div className="z-as-gradient-legal">
            <span>{copyright}</span>
            {legalLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                onClick={() => onNavigate?.(link)}
              >
                {link.label}
              </a>
            ))}
            <button
              type="button"
              onClick={() =>
                (scrollContainer?.current ?? window).scrollTo({
                  top: 0,
                  behavior: env.reduced ? "instant" : "smooth",
                })
              }
            >
              Back to top ↑
            </button>
          </div>
          <svg
            className="z-as-gradient-word"
            role="img"
            aria-label={brand}
            viewBox="0 0 1000 300"
            style={{
              maxHeight: "45%",
              transform: `translateY(${env.reduced ? 0 : (1 - progress) * 35}%)`,
            }}
          >
            <text
              x="0"
              y="294"
              fontFamily="Arial,Helvetica,sans-serif"
              fontSize="370"
              fontWeight="600"
              letterSpacing="-18"
              textLength="1000"
              lengthAdjust="spacingAndGlyphs"
              fill="currentColor"
              opacity=".57"
            >
              {brand}
            </text>
          </svg>
        </footer>
        <div
          className="z-as-gradient-cover"
          style={{ transform: `translateY(${-progress * 110}%)` }}
        >
          {children}
          <small>SCROLL ↓</small>
        </div>
      </div>
    </div>
  );
}
